import{_ as a,o as t,c as r,a3 as i}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Build guide","description":"Reuse Ordo deliberately through small, verifiable implementation slices.","frontmatter":{"title":"Build guide","description":"Reuse Ordo deliberately through small, verifiable implementation slices."},"headers":[],"relativePath":"build/index.md","filePath":"build/index.md","lastUpdated":1794376220000}'),n={name:"build/index.md"};function s(o,e,d,l,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="reuse-repair-prove-extend" tabindex="-1">Reuse, repair, prove, extend <a class="header-anchor" href="#reuse-repair-prove-extend" aria-label="Permalink to &quot;Reuse, repair, prove, extend&quot;">​</a></h1><p><strong>Do not import all of Ordo. Do not ignore the useful code we already have.</strong> Extract bounded behaviors, repair identified gaps, and connect them through tested contracts.</p><h2 id="start-with-evidence" tabindex="-1">Start with evidence <a class="header-anchor" href="#start-with-evidence" aria-label="Permalink to &quot;Start with evidence&quot;">​</a></h2><p>The <a href="./../reuse/">reuse map</a> separates the historical Rust/SQLite daemon, current rebuild, executor lab and streaming workshop. The <a href="./../reuse/source-audit">source audit</a> pins files and symbols to exact revisions. The <a href="./../reuse/harvest-plan">extraction plan</a> defines the boundary before code moves.</p><p>A source file&#39;s tests are not a current pass receipt. Private source is not automatically public teaching material.</p><h2 id="build-in-this-order" tabindex="-1">Build in this order <a class="header-anchor" href="#build-in-this-order" aria-label="Permalink to &quot;Build in this order&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Result</th></tr></thead><tbody><tr><td>S0</td><td>Review reuse rights, dependencies and contracts</td></tr><tr><td>S1</td><td>Establish durable jobs, leases and events</td></tr><tr><td>S2–S3</td><td>Preserve evidence, resolve proposals and publish atomically</td></tr><tr><td>S4–S5</td><td>Retrieve evidence and stream cited answers</td></tr><tr><td>S6–S7</td><td>Prove portability, then release a bounded hosted demonstration</td></tr></tbody></table><p>The <a href="./../project/roadmap">delivery roadmap</a> owns dependencies and exit criteria. This table is a reading aid, not another backlog.</p><h2 id="work-you-can-run-now" tabindex="-1">Work you can run now <a class="header-anchor" href="#work-you-can-run-now" aria-label="Permalink to &quot;Work you can run now&quot;">​</a></h2><p>From a checkout with Node.js 22+ and Python 3.10+:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>These commands validate and serve documentation plus synthetic examples. They do not start the research backend. The separate Rust example command and compiler pin are in <a href="./../engineering/clean-build">clean builds</a>.</p><h2 id="what-every-change-carries" tabindex="-1">What every change carries <a class="header-anchor" href="#what-every-change-carries" aria-label="Permalink to &quot;What every change carries&quot;">​</a></h2><p>A requirement, a bounded issue, relevant donor references, tests, atomic commits and a review receipt. Use the <a href="./../project/acceptance">acceptance register</a> for stable IDs and the <a href="./../engineering/twelve-factor">twelve-factor matrix</a> for operating properties.</p><p>Build once; test the artifact; promote that artifact with reviewed configuration. Keep application release, library publication and documentation deployment separate.</p><h2 id="first-implementation-target" tabindex="-1">First implementation target <a class="header-anchor" href="#first-implementation-target" aria-label="Permalink to &quot;First implementation target&quot;">​</a></h2><p>Extract DAG validation and idempotent job creation with transactional events. Exclude model calls, frontend work and live deployment. Follow with lease fencing and scoped replay before adding evidence extraction.</p><p><strong>Next:</strong> <a href="./../project/roadmap">Follow S0–S7 →</a></p>`,18)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
